-- «Batafsil» matnlari — Oybek, G'afur G'ulom, Zulfiya va Erkin Vohidov.

-- =================================== OYBEK ===================================

UPDATE fact_cards SET detail_uz = $$1905-yilda Toshkentning Govkush mahallasida tug'ilganman. Asl ismim — Musa Toshmuhammad o'g'li.

«Oybek» — mening adabiy taxallusim. Oilamiz hunarmand oila bo'lgan: otam bo'zchilik bilan shug'ullangan. Bolaligim eski shahar mahallalarida o'tgan va o'sha hayot keyinchalik asarlarimga kirgan. Men avval eski maktabda, keyin yangi tipdagi maktabda o'qiganman.$$
 WHERE topic_uz = $$Tug'ilishim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'oybek');

UPDATE fact_cards SET detail_uz = $$1922-yildan she'r yoza boshlaganman — o'shanda men o'n yetti yoshda edim.

Ijodim she'riyatdan boshlangan, keyin nasrga o'tganman va roman yozishga kelganman. Bunday yo'l ko'p yozuvchida uchraydi: she'r yozish tilni his qilishni o'rgatadi, nasr esa uzun matnni qurish mahoratini talab qiladi. Men umrimning oxirigacha — qariyb ellik yil davomida ijod qildim va bu davrda o'nlab kitob yaratdim.$$
 WHERE topic_uz = $$Ijodim boshlanishi$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'oybek');

UPDATE fact_cards SET detail_uz = $$Ilk she'riy to'plamlarim 1920–1930-yillarda chiqqan.

Ularda tabiat, yoshlik tuyg'ulari va zamon o'zgarishlari haqida yozilgan. Uslubim o'sha davr uchun yangi edi: men mumtoz aruz bilan bir qatorda erkin vazndan ham foydalanganman. She'rlarimda tasvir kuchli — bu keyinchalik nasrimga ham o'tgan: romanlarimda tabiat va shahar manzaralari she'riy tilda berilgan.$$
 WHERE topic_uz = $$She'riy to'plamlarim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'oybek');

UPDATE fact_cards SET detail_uz = $$1940-yilda «Qutlug' qon» romanimni yozdim.

Voqealar XX asr boshidagi Toshkentda kechadi. Roman markazida oddiy mehnatkash Yo'lchining taqdiri turadi: u qishloqdan shaharga keladi va og'ir hayot bilan yuzlashadi. Asarda mustamlaka davridagi jamiyat, boy va kambag'al o'rtasidagi tafovut, oddiy odamning qadr-qimmati mavzulari ko'tarilgan. Roman ko'p tillarga tarjima qilingan.$$
 WHERE topic_uz = $$«Qutlug' qon»$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'oybek');

UPDATE fact_cards SET detail_uz = $$«Navoiy» romanim 1944-yilda — Ikkinchi jahon urushi yillarida chiqqan.

Roman yozish uchun men XV asr tarixini, Hirot hayotini va Navoiy asarlarini chuqur o'rganganman: tarixiy manbalar, tazkiralar va shoirning o'z kitoblari ustida ishlaganman. Asarda Navoiy siymosi jonli inson sifatida — do'st, vazir, shoir va kurashchi qiyofasida ko'rsatilgan. Roman o'zbek tarixiy nasrining eng yirik namunalaridan biri sanaladi va u ko'plab tilga tarjima qilingan.$$
 WHERE topic_uz = $$«Navoiy» romani$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'oybek');

UPDATE fact_cards SET detail_uz = $$«Navoiy»dan keyin ham yirik asarlar yozganman: «Oltin vodiydan shabadalar», «Quyosh qoraymas» va «Ulug' yo'l».

«Quyosh qoraymas» urush yillari va odamlarning bu davrdagi taqdiriga bag'ishlangan. Har bir roman uchun men material to'plaganman: joylarga borganman, odamlar bilan suhbatlashganman, hujjatlarni o'rganganman. Yozuvchining ishi faqat yozish emas — u avvalo o'rganish va kuzatishdan iborat.$$
 WHERE topic_uz = $$Boshqa romanlarim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'oybek');

UPDATE fact_cards SET detail_uz = $$1963-yilda «Bolalik» xotira-qissamni yozdim.

Unda o'z bolaligim — Toshkentning eski mahallalari, hunarmandlar hayoti, bolalar o'yinlari, bayramlar va oilaviy urf-odatlar tasvirlangan. Asar bolalar uchun ham, kattalar uchun ham qiziqarli: unda XX asr boshidagi shahar hayoti jonli manzarada berilgan. Xotira asarlarining qimmati shundaki, ular o'tgan davr turmushini tarix kitoblari yozib qoldirmaydigan tafsilotlar bilan saqlaydi.$$
 WHERE topic_uz = $$«Bolalik»$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'oybek');

UPDATE fact_cards SET detail_uz = $$1943-yilda O'zbekiston Fanlar akademiyasining haqiqiy a'zosi — akademik bo'lganman.

Bu yozuvchi uchun kam uchraydigan hol: men badiiy ijod bilan bir qatorda ilmiy ish bilan ham shug'ullanganman. Adabiyotshunoslik bo'yicha maqolalar yozganman, Navoiy ijodini o'rganganman. Bunday qo'sh faoliyat menga tarixiy roman yozishda yordam bergan: ilmiy tekshirish malakasi materialni to'g'ri o'rganish imkonini bergan.$$
 WHERE topic_uz = $$Akademiklik$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'oybek');

UPDATE fact_cards SET detail_uz = $$Pushkinning «Yevgeniy Onegin», Lermontovning «Maskarad» va Molyerning asarlarini o'zbekchaga o'girganman.

«Yevgeniy Onegin» she'riy roman bo'lib, uni tarjima qilish alohida murakkab: unda maxsus band tuzilishi — «Onegin bandi» qo'llangan va uni saqlash kerak edi. Bunday tarjimalar o'zbek tilining imkoniyatlarini kengaytirgan: chet el asaridagi murakkab fikr va ohangni berish uchun yangi ifodalar izlashga to'g'ri kelgan.$$
 WHERE topic_uz = $$Tarjimalarim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'oybek');

UPDATE fact_cards SET detail_uz = $$1968-yilda Toshkentda vafot etganman.

Umrimning so'nggi yillarida sog'ligim yomonlashgan, ammo yozishdan to'xtamaganman. Ortimda romanlar, qissalar, she'riy to'plamlar, tarjimalar va ilmiy maqolalar qoldi. Asarlarim maktab va oliygoh dasturlariga kiritilgan, ular o'nlab tilga tarjima qilingan. Yozuvchi uchun eng katta natija — kitoblarining o'qilishda davom etishi.$$
 WHERE topic_uz = $$Umrimning oxiri$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'oybek');

UPDATE fact_cards SET detail_uz = $$Men Toshkentda va Leningrad (hozirgi Sankt-Peterburg) shahrida iqtisod yo'nalishida tahsil olganman.

Adabiyotchi bo'lish niyatidagi yigit uchun iqtisod g'alati tanlov bo'lib tuyulishi mumkin, ammo u menga jamiyat qanday ishlashini tushunish imkonini bergan. Leningraddagi yillar esa meni rus va jahon adabiyoti bilan yaqindan tanishtirgan: u yerda kutubxonalar, teatrlar va muzeylar bor edi. Bu tajriba keyinchalik romanlarimda asqotgan.$$
 WHERE topic_uz = $$O'qigan dargohlarim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'oybek');

UPDATE fact_cards SET detail_uz = $$Turmush o'rtog'im Zarifa Saidnosirova kimyogar olima edi.

U ilmiy ish bilan shug'ullangan va ayni paytda menga ijodda tayanch bo'lgan. Zarifa men haqimda xotiralar yozib qoldirgan — ular «Oybegim mening» nomi bilan nashr etilgan. Bunday xotiralar qimmatli: ular yozuvchining kundalik hayoti, ish tartibi va asarlar qanday yaratilgani haqida ma'lumot beradi. Kasal bo'lib qolganimda u menga yozishda yordam bergan.$$
 WHERE topic_uz = $$Turmush o'rtog'im$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'oybek');

UPDATE fact_cards SET detail_uz = $$«Navoiy» romanim uchun 1946-yilda Davlat mukofotiga sazovor bo'lganman.

Bu mukofot roman chiqqanidan ikki yil keyin berilgan va u asarning nafaqat o'zbek, balki umumittifoq miqyosida e'tirof etilganini bildirardi. Roman shu tariqa boshqa tillarga tarjima qilinib, keng o'quvchiga yetib borgan. Tarixiy mavzudagi asarning bunday baholanishi o'sha davr uchun ahamiyatli edi.$$
 WHERE topic_uz = $$Davlat mukofotim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'oybek');

UPDATE fact_cards SET detail_uz = $$«Navoiy» romanimdan avval ulug' shoir haqida shu nomdagi doston ham yozganman.

Doston she'riy asar bo'lib, unda Navoiy siymosi umumlashgan tarzda ko'rsatilgan. Keyinchalik men bu mavzuga qaytdim va uni roman shaklida — kengroq, tafsilotli qilib yozdim. Bir mavzuga ikki marta murojaat qilish yozuvchida uchraydi: birinchi urinish material to'plashga va mavzuni his qilishga yordam beradi, ikkinchisi esa uni to'liq ochadi.$$
 WHERE topic_uz = $$Navoiy haqidagi dostonim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'oybek');

UPDATE fact_cards SET detail_uz = $$Urushdan keyingi yillarda O'zbekiston Yozuvchilar uyushmasiga raislik qilganman.

Uyushma yozuvchilarni birlashtiruvchi tashkilot bo'lib, u nashr ishlarini tashkil qilar, yosh ijodkorlarni qo'llab-quvvatlar va adabiy anjumanlar o'tkazardi. Rahbarlik ishi ko'p vaqt olardi va ijodga xalaqit berardi, ammo u orqali boshqa yozuvchilarga yordam berish mumkin edi. Bu davr adabiyot uchun oson emasdi va har bir qaror mas'uliyat talab qilardi.$$
 WHERE topic_uz = $$Yozuvchilar uyushmasidagi ishim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'oybek');

UPDATE fact_cards SET detail_uz = $$Toshkentda men yashagan uyda bugun Oybek uy-muzeyi faoliyat yuritadi.

Muzeyda mening shaxsiy buyumlarim, kutubxonam, qo'lyozmalarim va kitoblarim saqlanadi. Ish stolim va yozuv anjomlarim ham o'z joyida qoldirilgan. Bunday muzeylar yozuvchining hayotini yaqindan ko'rsatadi: o'quvchi u qanday sharoitda ishlaganini, qanday kitoblar o'qiganini ko'radi. Muzeyga maktab o'quvchilari va adabiyot ixlosmandlari keladi.$$
 WHERE topic_uz = $$Uy-muzeyim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'oybek');

UPDATE fact_cards SET detail_uz = $$Toshkent metrosining bekatlaridan biri va bir qancha ko'chalar mening nomim bilan ataladi.

Bundan tashqari maktablar, kutubxonalar va O'zbekiston Fanlar akademiyasining ba'zi tuzilmalari shu nomni yuritadi. Asarlarim maktab dasturida o'rganiladi va qayta-qayta nashr etiladi. 2005-yilda tavalludimning 100 yilligi keng nishonlangan. Nom bilan atash — jamiyat kimni qadrlashini ko'rsatadigan belgi.$$
 WHERE topic_uz = $$Nomimdagi joylar$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'oybek');

-- ================================ G'AFUR G'ULOM ================================

UPDATE fact_cards SET detail_uz = $$1903-yilda Toshkentda tug'ilganman.

Oilamiz oddiy oila bo'lgan; otam savodli kishi edi va uyimizda kitob bo'lgan. Bolaligim eski shahar mahallalarida o'tgan — o'sha hayot, ko'chalar, bozorlar va odamlar keyinchalik «Shum bola» qissamga kirgan. Men avval eski maktabda, keyin rus-tuzem maktabida o'qiganman.$$
 WHERE topic_uz = $$Tug'ilishim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'gafur-gulom');

UPDATE fact_cards SET detail_uz = $$«Shum bola» qissamni 1936-yilda yozdim.

Unda o'z bolaligim va XX asr boshidagi Toshkent hayoti hikoya qilinadi: mahalla, bozor, hunarmandlar, bolalar o'yinlari va sarguzashtlar. Bosh qahramon — quvnoq, topqir va shumtaka bola; u boshiga tushgan qiyinchiliklardan hazil va aql bilan chiqadi. Qissa tili jonli va kulgili. U bugun ham eng ko'p o'qiladigan o'zbek bolalar kitoblaridan biri; asosida film ham suratga olingan.$$
 WHERE topic_uz = $$«Shum bola»$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'gafur-gulom');

UPDATE fact_cards SET detail_uz = $$Ilk she'riy to'plamlarim 1930-yillar boshida chiqqan.

Ularda o'sha davr hayoti, mehnat va o'zgarishlar mavzulari ko'tarilgan. Men she'riyatga yangi ohang olib kirishga harakat qilganman: erkin vazn, jonli xalq tili va hazil aralash ifoda. Keyinchalik she'rlarim chuqurlashib borgan — ularda inson taqdiri, urush va tinchlik, hayotning ma'nosi haqidagi o'ylar paydo bo'lgan.$$
 WHERE topic_uz = $$She'riy to'plamlarim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'gafur-gulom');

UPDATE fact_cards SET detail_uz = $$Mashhur she'rlarim orasida «Qish va shoirlar», «Non» va «Toshkent» bor.

«Non» she'rida oddiy non orqali mehnat qadri va odamlarning bir-biriga bog'liqligi ko'rsatilgan: nonni yetkazish uchun dehqondan novvoygacha ko'p odam mehnat qiladi. «Toshkent» she'ri esa tug'ilgan shahrimga bag'ishlangan. Bu she'rlar maktab darsliklarida o'qitiladi va ular sodda mavzuni chuqur ma'no bilan berish namunasi sanaladi.$$
 WHERE topic_uz = $$Mashhur she'rlarim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'gafur-gulom');

UPDATE fact_cards SET detail_uz = $$«Netay» va «Yodgor» qissalarimni yozganman.

«Yodgor» qissasi urushdan oldingi davrda yozilgan bo'lib, unda oila, farzand va mas'uliyat mavzulari ko'tariladi. Qissa janri roman bilan hikoya orasidagi shakl: u bitta voqeaga qaratilgan, ammo qahramonlarni chuqur ochib berishga imkon beradi. Mening qissalarimda ham hazil, ham jiddiy o'ylar birga yuradi — bu mening uslubimning o'ziga xos jihati.$$
 WHERE topic_uz = $$Qissalarim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'gafur-gulom');

UPDATE fact_cards SET detail_uz = $$1965-yilda «Mening o'g'rigina bolam» hikoyamni yozdim.

Hikoyada bola va uning xatosi haqida so'z boradi, ammo asosiy mavzu — kattalarning bolaga munosabati. Sarlavhadagi «o'g'rigina» so'zi erkalash ohangida aytilgan: u jazolash emas, tushunish kerakligiga ishora qiladi. Bu hikoya tarbiya haqida: bola xato qilsa, uni haydash emas, unga to'g'ri yo'lni ko'rsatish lozim. Asar maktab dasturida o'rganiladi.$$
 WHERE topic_uz = $$«Mening o'g'rigina bolam»$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'gafur-gulom');

UPDATE fact_cards SET detail_uz = $$1943-yilda O'zbekiston Fanlar akademiyasining haqiqiy a'zosi bo'lganman.

Bu shuni bildiradiki, men badiiy ijod bilan bir qatorda ilmiy ish bilan ham shug'ullanganman: adabiyotshunoslik va folklor bo'yicha maqolalar yozganman. Xalq og'zaki ijodini — ertak, maqol va qo'shiqlarni to'plash va o'rganish menga alohida qiziq edi, chunki adabiyot aynan shu manbadan oziqlanadi. Shu yili Oybek ham akademik bo'lgan.$$
 WHERE topic_uz = $$Akademiklik$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'gafur-gulom');

UPDATE fact_cards SET detail_uz = $$Ilmiy ishlarim orasida «Folklordan o'rganaylik» va «Navoiy va zamonamiz» maqolalarim bor.

Birinchisida men yozuvchilarni xalq og'zaki ijodidan — ertak, maqol, latifa va qo'shiqlardan o'rganishga chaqirganman: ularda til boyligi va xalq donoligi jamlangan. Ikkinchisida Navoiy merosining bugungi kun uchun ahamiyati haqida yozganman. Bu maqolalar adabiyotshunoslikda o'z o'rniga ega.$$
 WHERE topic_uz = $$Ilmiy ishlarim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'gafur-gulom');

UPDATE fact_cards SET detail_uz = $$Shekspirning «Otello» va «Qirol Lir» fojialarini o'zbekchaga o'girganman.

Shekspir tarjimasi eng murakkab ishlardan biri: unda she'riy o'lchov, so'z o'yinlari va yuksak uslub bor. Bu asarlar o'zbek teatri sahnasida qo'yilgan va ular milliy teatrimizning rivojiga hissa qo'shgan. Tarjima orqali men o'zbek tilining imkoniyatini sinab ko'rganman — jahon klassikasini berish uchun til yetarli darajada boy ekanini ko'rsatganman.$$
 WHERE topic_uz = $$Tarjimalarim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'gafur-gulom');

UPDATE fact_cards SET detail_uz = $$1966-yilda vafot etganman; 2000-yilda menga vafotimdan keyin yuksak davlat mukofoti berilgan.

Ortimda she'rlar, qissalar, hikoyalar, tarjimalar va ilmiy maqolalar qoldi. Asarlarim maktab dasturida o'rganiladi va qayta-qayta nashr etiladi. Toshkentda uy-muzeyim ishlaydi. Mustaqillik yillarida ijodim qayta baholanib, adabiyotimiz tarixidagi o'rnim e'tirof etilgan.$$
 WHERE topic_uz = $$Umrimning oxiri$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'gafur-gulom');

UPDATE fact_cards SET detail_uz = $$Men bolaligimda ota-onamdan erta ayrilib, yetim o'sganman.

Shu sababli yetimlar mavzusi ijodimda alohida o'rin tutadi: men bu holatni kitobdan emas, o'z tajribamdan bilardim. Urush yillarida yozgan «Sen yetim emassan» she'rim ham shundan tug'ilgan. Yoshligim og'ir kechgan — men erta mehnatga kirishganman. Ammo shu qiyinchilik menga odamlarning dardini tushunishni o'rgatgan.$$
 WHERE topic_uz = $$Yetim o'sganim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'gafur-gulom');

UPDATE fact_cards SET detail_uz = $$Yoshligimda bosmaxonada harf teruvchi bo'lib ishlaganman, keyin o'qituvchilik qilganman.

Harf teruvchi — kitob va gazeta matnini metall harflardan yig'adigan ishchi; bu ish diqqat va aniqlikni talab qilardi. Bosmaxonada ishlash menga matn bilan ishlashni o'rgatgan va adabiyot dunyosiga yaqinlashtirgan. O'qituvchilik esa bolalar bilan muloqot qilish tajribasini bergan — bu keyinchalik bolalar uchun yozishimda asqotgan.$$
 WHERE topic_uz = $$Ilk kasblarim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'gafur-gulom');

UPDATE fact_cards SET detail_uz = $$Ilk she'rim «Go'zallik nimada?» deb atalgan va u 1923-yilda bosilgan.

Sarlavhadagi savol butun ijodim uchun ramziy: men umr bo'yi go'zallikni hashamatda emas, oddiy narsalarda — mehnatda, do'stlikda, sodda hayotda izlaganman. Yosh muallif uchun birinchi bosilgan she'r katta voqea: bu uning ovozi eshitila boshlaganini bildiradi. Shundan keyin men muntazam yozdim va matbuot bilan aloqani uzmadim.$$
 WHERE topic_uz = $$Ilk she'rim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'gafur-gulom');

UPDATE fact_cards SET detail_uz = $$Ikkinchi jahon urushi yillarida «Sen yetim emassan» she'rimni yozganman.

O'sha yillarda O'zbekistonga bosib olingan hududlardan minglab yetim bola olib kelingan va o'zbek oilalari ularni farzandlikka olgan. Toshkentlik temirchi Shomahmudov oilasi 15 nafar bolani o'z bag'riga olgan. She'r aynan shu haqda: yetim qolgan bola yolg'iz emas, uning atrofida uni o'z farzandidek qabul qiladigan odamlar bor. She'r ko'p tillarga tarjima qilingan va u xalqimiz mehr-oqibatining ramziga aylangan.$$
 WHERE topic_uz = $$«Sen yetim emassan» she'ri$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'gafur-gulom');

UPDATE fact_cards SET detail_uz = $$«Mushtum» hajviy jurnali tahririyatida ishlaganman.

Jurnal savodsizlik, poraxo'rlik, dangasalik va ikkiyuzlamachilikni kulgi orqali tanqid qilardi; unda felyeton, hajviy hikoya va karikaturalar bosilardi. Abdulla Qodiriy ham shu jurnalning faol mualliflaridan bo'lgan. Hazil menga yaqin edi: men jiddiy fikrni kulgi bilan aytishni afzal ko'rardim, chunki kulgi odamni xafa qilmaydi, ammo o'ylashga majbur qiladi.$$
 WHERE topic_uz = $$«Mushtum» jurnalida$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'gafur-gulom');

UPDATE fact_cards SET detail_uz = $$1963-yilda menga «O'zbekiston xalq shoiri» faxriy unvoni berilgan.

Bu unvon adabiyotdagi uzoq yillik mehnat va xalq e'tirofi uchun beriladi. Men uchun undan ham muhimi shu ediki, she'rlarim va qissalarim odamlar tomonidan o'qilardi, «Shum bola» esa bolalar sevib o'qiydigan kitobga aylangandi. Yozuvchi uchun eng katta mukofot — kitobining qo'ldan qo'ymay o'qilishi.$$
 WHERE topic_uz = $$Xalq shoiri unvonim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'gafur-gulom');

UPDATE fact_cards SET detail_uz = $$Toshkentdagi katta adabiyot va san'at nashriyoti, metro bekati va madaniyat markazi mening nomim bilan ataladi.

Nashriyot badiiy adabiyot, she'riy to'plamlar va tarjimalarni chop etadi — bu ramziy, chunki men butun umrim davomida kitob bilan ishlaganman. Bundan tashqari ko'chalar, maktablar va kutubxonalar shu nomni yuritadi; Toshkentda uy-muzeyim faoliyat yuritadi.$$
 WHERE topic_uz = $$Nomimdagi joylar$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'gafur-gulom');

-- ================================== ZULFIYA ==================================

UPDATE fact_cards SET detail_uz = $$1915-yilda Toshkentda, hunarmand oilasida tug'ilganman.

Otam temirchi bo'lgan. Oilamizda kitobga hurmat bor edi va men yoshligimdan she'r o'qishni yaxshi ko'rardim. O'sha davrda qizlarning o'qishi hali keng tarqalmagan edi, shuning uchun ta'lim olish imkoniyati men uchun katta baxt bo'lgan. Bu holat keyingi ijodimga ta'sir qilgan: men she'rlarimda ayollarning bilim olishi va o'z o'rnini topishi haqida ko'p yozganman.$$
 WHERE topic_uz = $$Tug'ilishim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'zulfiya');

UPDATE fact_cards SET detail_uz = $$1931–1934-yillarda xotin-qizlar bilim yurtida o'qiganman.

Bunday bilim yurtlari qizlar uchun maxsus ochilgan va ular o'qituvchi tayyorlardi. U yerda men adabiyot, tarix va pedagogikadan saboq olganman, ayni paytda she'r mashqlarini davom ettirganman. Ustozlarim ijodimni qo'llab-quvvatlagan. Aynan shu yillarda mening ilk she'rlarim matbuotda bosila boshlagan.$$
 WHERE topic_uz = $$O'qishim$$ AND hero_id = (SELECT id FROM heroes WHERE slug = 'zulfiya');

UPDATE fact_cards SET detail_uz = $$1935–1938-yillarda Fanlar akademiyasining Til va adabiyot institutida ishlaganman.

U yerda men adabiyot tarixini o'rganganman va ilmiy ish bilan shug'ullanganman. Bu tajriba menga mumtoz she'riyatni chuqurroq tushunish imkonini bergan: Navoiy, Nodira va boshqa shoirlar ijodini o'rganish o'z she'riyatimni boyitgan. Shoir uchun o'qish va o'rganish yozish kabi zarur.$$
